export function normalize(weights){
  if(weights.length !== 6 || weights.some(w=>!Number.isFinite(w)||w<0)) throw new Error('Six finite nonnegative weights required.');
  const total=weights.reduce((a,b)=>a+b,0);
  return total ? weights.map(w=>w/total) : weights.map(()=>1/6);
}
// Seeded, illustrative residual paths: these do not fit or reproduce the six models.
export function sample(t){
  const trend=1.79+.0028*t+.025*Math.sin(t/17);
  const season=.045*Math.sin(2*Math.PI*t/12);
  const residual=.018*Math.sin(t*1.73)+.012*Math.cos(t*.79);
  return {trend,season,residual,log:trend+season+residual,price:Math.exp(trend+season+residual)};
}
export function residualForecast(t,i){
  const previous=sample(t-1).residual;
  return [.55*previous+.007,.30*previous-.009,.22*previous+.004,
    .018*Math.sin(t*1.73+.35)+.018,.022*Math.cos(t*.79+.3)-.018,
    .40*previous-.003][i];
}
export function forecast(t,weights){
  const w=normalize(weights),s=sample(t);
  const residual=w.reduce((sum,weight,i)=>sum+weight*residualForecast(t,i),0);
  return Math.exp(s.trend+s.season+residual);
}
export function demoMetrics(weights){
  const errors=Array.from({length:24},(_,i)=>{const t=36+i,actual=sample(t).price;return {error:forecast(t,weights)-actual,actual};});
  return {mae:errors.reduce((a,e)=>a+Math.abs(e.error),0)/24,
    mape:100*errors.reduce((a,e)=>a+Math.abs(e.error/e.actual),0)/24};
}
